begin;
do $$
declare a uuid;b uuid;c uuid;e uuid;doc uuid:=gen_random_uuid();rid uuid;mid uuid:=gen_random_uuid();report uuid:=gen_random_uuid();v int;seen jsonb;note_id uuid;event_id uuid;
begin
 perform set_config('request.jwt.claims','{"iss":"https://securetoken.google.com/mymap-a3ae4","aud":"mymap-a3ae4","sub":"catalog-qa-alice-20261008"}',true);a:=public.mm_identity();
 perform set_config('request.jwt.claims','{"iss":"https://securetoken.google.com/mymap-a3ae4","aud":"mymap-a3ae4","sub":"catalog-qa-bob-20261008"}',true);b:=public.mm_identity();
 perform set_config('request.jwt.claims','{"iss":"https://securetoken.google.com/mymap-a3ae4","aud":"mymap-a3ae4","sub":"catalog-qa-carol-20261008"}',true);c:=public.mm_identity();
 perform set_config('request.jwt.claims','{"iss":"https://securetoken.google.com/mymap-a3ae4","aud":"mymap-a3ae4","sub":"catalog-qa-eve-20261008"}',true);e:=public.mm_identity();
 insert into public.vc_connections(requester_id,addressee_id,status,share_exact_location) values(a,b,'accepted',true),(a,c,'accepted',true);
 insert into public.vc_live_presence(user_id,latitude,longitude,expires_at) values(a,21.02851,105.85423,now()+interval '5 minutes');
 perform set_config('request.jwt.claims','{"iss":"https://securetoken.google.com/mymap-a3ae4","aud":"mymap-a3ae4","sub":"catalog-qa-alice-20261008"}',true);
 execute 'set local role anon';
 v:=public.mm_doc_save(doc,'trip','{"name":"Fixture trip","mode":"motorbike","startsAt":1791432000000,"stops":[{"id":"stop-one","name":"A","latitude":21,"longitude":105,"stayMinutes":0},{"id":"stop-two","name":"B","latitude":21.1,"longitude":105.1,"stayMinutes":5}],"votes":{},"favorite":false}',0,array[b,c],null);
 if v<>1 then raise exception 'Initial document version';end if;
 begin perform public.mm_doc_save(doc,'trip','{}',0,array[b,c],null);raise exception 'Duplicate version accepted';exception when others then if sqlerrm<>'version_conflict' then raise;end if;end;
 begin perform public.mm_doc_save(doc,'trip','{}',null,array[b,c],null);raise exception 'Null version accepted';exception when others then if sqlerrm<>'version_conflict' then raise;end if;end;
 begin perform public.mm_doc_save(report,'road_report','{}',0,'{}',now()+interval '1 hour');raise exception 'Missing coordinates accepted';exception when others then if sqlerrm<>'invalid_report' then raise;end if;end;
 perform public.mm_set_friend_privacy(b,'precise');perform public.mm_set_global_privacy('fuzzy');
 seen:=public.mm_post_map_note('Private pin','📍',21.02851,105.85423,b);note_id:=(seen->>'id')::uuid;
 seen:=public.mm_friend_interaction(b,'heart','{"senderId":"forged","url":"private-file"}');event_id:=(seen->>'id')::uuid;
 if seen->>'senderId'<>a::text or seen->'metadata' ? 'url' then raise exception 'Interaction spoofing';end if;
 rid:=public.mm_create_room('Fixture chat',array[b]);
 if public.mm_create_room('Again',array[b])<>rid then raise exception 'Direct room duplication';end if;
 perform public.mm_send_message(mid,rid,'text','Private fixture',0);
 perform public.mm_send_message(mid,rid,'text','Private fixture',0);
 if (select count(*) from public.mm_messages where id=mid)<>1 then raise exception 'Message idempotency';end if;
 begin perform public.mm_send_message(mid,rid,'text','Changed',0);raise exception 'Message ID reused';exception when others then if sqlerrm<>'message_id_conflict' then raise;end if;end;
 perform set_config('request.jwt.claims','{"iss":"https://securetoken.google.com/mymap-a3ae4","aud":"mymap-a3ae4","sub":"catalog-qa-bob-20261008"}',true);
 v:=public.mm_doc_save(doc,'trip','{"name":"Collaborator edit","mode":"motorbike","startsAt":1791432000000,"stops":[{"id":"stop-one","name":"A","latitude":21,"longitude":105,"stayMinutes":0},{"id":"stop-two","name":"B","latitude":21.1,"longitude":105.1,"stayMinutes":5}],"votes":{},"favorite":false}',1,array[b,c],null);
 if v<>2 then raise exception 'Collaboration with friends of owner';end if;
 perform public.mm_trip_vote(doc,'stop-one');perform public.mm_trip_vote(doc,'stop-two');
 if (select count(*) from public.mm_trip_ballots where document_id=doc and user_id=b)<>1 or (select stop_id from public.mm_trip_ballots where document_id=doc and user_id=b)<>'stop-two' then raise exception 'Trip ballots duplicate';end if;
 begin perform public.mm_trip_vote(doc,'missing');raise exception 'Invalid stop voted';exception when others then if sqlerrm<>'invalid_stop' then raise;end if;end;
 begin perform public.mm_doc_save(gen_random_uuid(),'trip','{"name":"Fixture trip","mode":"motorbike","startsAt":1791432000000,"stops":[{"id":"stop-one","name":"A","latitude":999,"longitude":105,"stayMinutes":0},{"id":"stop-two","name":"B","latitude":21.1,"longitude":105.1,"stayMinutes":5}],"votes":{},"favorite":false}',0,'{}',null);raise exception 'Invalid route coordinates accepted';exception when others then if sqlerrm<>'invalid_itinerary_point' then raise;end if;end;
 v:=public.mm_doc_save(doc,'trip','{"name":"Fixture trip","mode":"motorbike","startsAt":1791432000000,"stops":[{"id":"stop-one","name":"A","latitude":21,"longitude":105,"stayMinutes":0},{"id":"stop-three","name":"B","latitude":21.1,"longitude":105.1,"stayMinutes":5}],"votes":{},"favorite":false}',2,array[b,c],null);
 if exists(select 1 from public.mm_trip_ballots where document_id=doc) then raise exception 'Ballot for removed stop retained';end if;
 seen:=public.mm_map_notes();if not exists(select 1 from jsonb_array_elements(seen) n where n->>'id'=note_id::text and(n->>'latitude')::float8=21.03) then raise exception 'Map note ignored privacy';end if;
 seen:=public.mm_friend_interactions();if not exists(select 1 from jsonb_array_elements(seen) n where n->>'id'=event_id::text) then raise exception 'Recipient interaction absent';end if;
 seen:=public.mm_live_friends();
 if not exists(select 1 from jsonb_array_elements(seen) f where f->>'user_id'=a::text and (f->>'latitude')::float8=21.03 and f->>'is_fuzzy'='true') then raise exception 'Fuzzy RPC wrong';end if;
 if exists(select 1 from public.vc_live_presence where user_id=a) then raise exception 'Raw coordinates bypass privacy';end if;
 if not exists(select 1 from public.mm_messages where id=mid) then raise exception 'Recipient cannot read message';end if;
 if not exists(select 1 from public.vc_notifications where user_id=b and payload->>'messageId'=mid::text) then raise exception 'Message notification absent';end if;
 perform public.mm_chat_state(rid,true,true);perform public.mm_chat_react(mid,'❤️');
 begin perform public.mm_cancel_message(mid,rid);raise exception 'Recipient canceled another sender';exception when others then if sqlerrm<>'not_sender' then raise;end if;end;
 begin perform public.mm_doc_delete(doc);raise exception 'Collaborator deleted owner document';exception when others then if sqlerrm<>'not_owner' then raise;end if;end;
 perform set_config('request.jwt.claims','{"iss":"https://securetoken.google.com/mymap-a3ae4","aud":"mymap-a3ae4","sub":"catalog-qa-eve-20261008"}',true);
 if exists(select 1 from public.mm_documents where id=doc) or exists(select 1 from public.mm_messages where id=mid) or exists(select 1 from public.mm_rooms where id=rid) then raise exception 'Stranger bypassed RLS';end if;
 if private.mm_chat_object(rid::text||'/'||a::text||'/'||mid::text) then raise exception 'Stranger accessed chat media';end if;
 if exists(select 1 from jsonb_array_elements(public.mm_map_notes()) n where n->>'id'=note_id::text) or jsonb_array_length(public.mm_friend_interactions())<>0 then raise exception 'Stranger read social feed';end if;
 if exists(select 1 from public.mm_trip_ballots where document_id=doc) then raise exception 'Stranger read trip ballots';end if;
 begin perform public.mm_friend_interaction(a,'heart','{}');raise exception 'Stranger interacted';exception when others then if sqlerrm<>'invalid_interaction' then raise;end if;end;
 begin perform public.mm_send_message(gen_random_uuid(),rid,'text','Blocked',0);raise exception 'Stranger sent message';exception when others then if sqlerrm<>'not_room_member' then raise;end if;end;
 perform set_config('request.jwt.claims','{"iss":"https://securetoken.google.com/mymap-a3ae4","aud":"mymap-a3ae4","sub":"catalog-qa-alice-20261008"}',true);
 perform public.mm_cancel_message(mid,rid);perform public.mm_cancel_message(mid,rid);
 if exists(select 1 from public.mm_messages where id=mid) then raise exception 'Canceled message retained';end if;
 if private.mm_chat_object(rid::text||'/'||a::text||'/'||mid::text) then raise exception 'Canceled media readable';end if;
 begin perform public.mm_send_message(mid,rid,'text','Private fixture',0);raise exception 'Canceled message revived';exception when others then if sqlerrm<>'message_canceled' then raise;end if;end;
 perform public.mm_doc_delete(doc);perform public.mm_doc_delete(doc);
 begin perform public.mm_doc_save(doc,'trip','{}',0,array[b,c],null);raise exception 'Deleted document revived';exception when others then if sqlerrm<>'document_deleted' then raise;end if;end;
 perform set_config('request.jwt.claims','{"iss":"https://securetoken.google.com/mymap-a3ae4","aud":"mymap-a3ae4","sub":"catalog-qa-bob-20261008"}',true);
 if not exists(select 1 from jsonb_array_elements_text(public.mm_doc_deletions()) t where t.value=doc::text) then raise exception 'Collaborator missed tombstone';end if;
 perform set_config('request.jwt.claims','{"iss":"https://securetoken.google.com/mymap-a3ae4","aud":"mymap-a3ae4","sub":"catalog-qa-alice-20261008"}',true);
 perform public.mm_set_presence_pause(true,null);
 execute 'reset role';
 insert into public.vc_live_presence(user_id,latitude,longitude,expires_at) values(a,22,106,now()+interval '5 minutes');
 if exists(select 1 from public.vc_live_presence where user_id=a) then raise exception 'Paused publisher resurfaced';end if;
 execute 'set local role anon';
 perform set_config('request.jwt.claims','{}',true);
 begin perform public.mm_live_friends();raise exception 'Unsigned caller allowed';exception when sqlstate '28000' then null;end;
 execute 'reset role';
end $$;
rollback;
select 'PASS: version CAS, collaborators, validation, chat idempotency, cancellation, deleted-document tombstones, recipient/stranger RLS, media ACL, notifications, trip ballots, private map notes and interactions, fuzzy privacy, pause race, unsigned caller' as result;
